import '../core/network/api_client.dart'; import '../models/product_variant.dart'; class ProductVariantRepository { ProductVariantRepository(this._api); final ApiClient _api; Future<List<ProductVariantModel>> byProduct(String id) async { final r=await _api.get('/api/product-variants/product/$id',authorized:false); return (r as List).whereType<Map<String,dynamic>>().map(ProductVariantModel.fromJson).toList(); } }